import { useCallback, useEffect, useMemo, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { apiBlobRequest, apiRequest, apiRequestWithHeaders } from '../api'
import { ListPagination } from '../components/ListControls'
import { showError } from '../format'
import { paginationFromHeaders } from '../pagination'
import type { Role, User } from '../types'

type CourseResult = { course_id: number; course_name: string; classes: { class_id: number; class_code: string; enrollment_status: string }[]; final_score: string | null; result: string; grade_breakdown: unknown; finalized_at: string | null }
type Transcript = { student_id: number; student_code: string | null; student_name: string; issued_on: string; courses: CourseResult[]; course_average: string | null; total: number; page: number; page_size: number; pages: number }
type TuitionPayment = { id: number; receipt_code: string; amount_vnd: string; paid_on: string; method: string; reversed: boolean; installment_remaining_vnd: string }
type Installment = { id: number; number: number; due_date: string; amount_due_vnd: string; paid_vnd: string; remaining_vnd: string; status: string; payments: TuitionPayment[] }
type TuitionPlan = { plan_id: number; class_id: number; class_code: string | null; total_due_vnd: string; discounts: { amount_vnd: string; status: string }[]; installments: Installment[] }
type TuitionResponse = { plans: TuitionPlan[]; total: number; page: number; page_size: number; pages: number }
type SurveyQuestion = { id: number; position: number; prompt: string; question_type: 'rating' | 'text'; is_required: boolean; scale_min: number | null; scale_max: number | null }
type StudentSurvey = { survey_id: number; title: string; class_id: number; class_name: string; deadline: string; responded: boolean; questions: SurveyQuestion[] }
type GraduationStudent = { student_id: number; student_code: string | null; student_name: string; eligible: boolean; reasons?: string[]; reason_details?: string[] }
type Program = { id: number; code: string; name: string }
type SurveyReport = { survey_id: number; title: string; class_id: number; class_name: string | null; response_count: number; questions: { question_id: number; prompt: string; question_type: 'rating' | 'text'; response_count: number; average: number | null }[]; text_answers: { question_id: number; prompt: string; answer: string }[] }
type SurveyComparison = { classes: SurveyReport[]; total: number; page: number; page_size: number }

const money = (value: string | number) => `${Number(value).toLocaleString('vi-VN')} ₫`
const dateTime = (value: string) => new Date(value).toLocaleString('vi-VN')
function PageFrame({ eyebrow, title, description, children }: { eyebrow: string; title: string; description?: string; children: ReactNode }) {
  return <div className="page-stack"><header className="section-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description ? <p>{description}</p> : null}</div></header>{children}</div>
}

export function TuitionPage({ user, notify }: { user: User; notify: (message: string) => void }) {
  const [data, setData] = useState<TuitionResponse | null>(null)
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [installmentId, setInstallmentId] = useState('')
  const [amount, setAmount] = useState('')
  const [method, setMethod] = useState<'cash' | 'bank_transfer'>('bank_transfer')
  const load = useCallback(() => {
    const isStudent = user.roles.includes('student') && !user.roles.some((role) => ['admin', 'accountant'].includes(role))
    apiRequest<TuitionResponse>(isStudent ? `/students/me/tuition?page=${page}&page_size=20` : `/tuition-payments?page=${page}&page_size=20`)
      .then((result) => { setError(''); setData(result) }).catch((reason: unknown) => { setError(showError(reason)); notify(showError(reason)) }).finally(() => setLoading(false))
  }, [notify, page, user.roles])
  useEffect(load, [load])
  const studentView = user.roles.includes('student') && !user.roles.some((role) => ['admin', 'accountant'].includes(role))
  const payments = useMemo(() => data && 'items' in data ? (data as unknown as { items: TuitionPayment[] }).items : [], [data])
  const plans = useMemo(() => data && 'plans' in data ? (data as TuitionResponse).plans : [], [data])
  const downloadReceipt = async (id: number) => {
    try { const blob = await apiBlobRequest(`/tuition-payments/${id}/receipt.pdf`); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `receipt-${id}.pdf`; anchor.click(); URL.revokeObjectURL(url) }
    catch (reason) { notify(showError(reason)) }
  }
  const recordPayment = async (event: FormEvent) => {
    event.preventDefault()
    try {
      await apiRequest(`/tuition-installments/${Number(installmentId)}/payments`, { method: 'POST', body: JSON.stringify({ amount_vnd: Number(amount), method, paid_on: new Date().toISOString().slice(0, 10), idempotency_key: crypto.randomUUID() }) })
      notify('Đã ghi nhận khoản thu.'); setInstallmentId(''); setAmount(''); load()
    } catch (reason) { notify(showError(reason)) }
  }
  const reversePayment = async (payment: TuitionPayment) => {
    const reason = window.prompt(`Lý do hoàn tác biên lai ${payment.receipt_code}`)
    if (!reason?.trim()) return
    try { await apiRequest(`/tuition-payments/${payment.id}/reverse`, { method: 'POST', body: JSON.stringify({ reason: reason.trim(), idempotency_key: crypto.randomUUID() }) }); notify('Đã ghi nhận hoàn tác giao dịch.'); load() }
    catch (failure) { notify(showError(failure)) }
  }
  return <PageFrame eyebrow="TÀI CHÍNH · SPRINT 7" title="Học phí và giao dịch" description="Theo dõi kế hoạch học phí, công nợ và lịch sử biên lai.">
    {error ? <div className="notice notice-error" role="alert">{error}</div> : null}
    {!studentView ? <form className="panel form-panel finance-entry" onSubmit={recordPayment}><div className="panel-heading"><div><span className="eyebrow">THU HỌC PHÍ</span><h2>Ghi nhận khoản thanh toán</h2></div></div><label className="form-field"><span>Mã đợt học phí</span><input inputMode="numeric" min="1" required value={installmentId} onChange={(event) => setInstallmentId(event.target.value)} /></label><label className="form-field"><span>Số tiền (VND)</span><input inputMode="numeric" min="1" required type="number" value={amount} onChange={(event) => setAmount(event.target.value)} /></label><label className="form-field"><span>Phương thức</span><select value={method} onChange={(event) => setMethod(event.target.value as 'cash' | 'bank_transfer')}><option value="bank_transfer">Chuyển khoản</option><option value="cash">Tiền mặt</option></select></label><button className="button button-primary" type="submit">Ghi nhận thanh toán</button><p className="form-help">Backend kiểm tra số dư, quyền kế toán và khóa idempotency để chống ghi trùng.</p></form> : null}
    {loading ? <div className="panel loading-panel" aria-live="polite">Đang tải dữ liệu tài chính…</div> : studentView ? plans.length ? plans.map((plan) => <section className="panel finance-plan" key={plan.plan_id}><div className="panel-heading"><div><span className="eyebrow">{plan.class_code ?? `Lớp ${plan.class_id}`}</span><h2>Kế hoạch #{plan.plan_id}</h2></div><strong>{money(plan.total_due_vnd)}</strong></div><div className="finance-installments">{plan.installments.map((item) => <article className="finance-installment" key={item.id}><div><strong>Đợt {item.number}</strong><span>Hạn {new Date(`${item.due_date}T00:00:00`).toLocaleDateString('vi-VN')}</span></div><div><strong>{money(item.remaining_vnd)}</strong><span>Đã đóng {money(item.paid_vnd)} · {item.status}</span></div>{item.payments.map((payment) => <button className="button button-quiet" key={payment.id} onClick={() => downloadReceipt(payment.id)} type="button">Biên lai {payment.receipt_code} · {payment.reversed ? 'Đã hoàn tác' : money(payment.amount_vnd)}</button>)}</article>)}</div></section>) : <div className="panel empty-state">Chưa có kế hoạch học phí.</div> : payments.length ? <section className="panel table-panel"><div className="table-scroll"><table className="data-table"><thead><tr><th>Biên lai</th><th>Ngày thu</th><th>Phương thức</th><th>Số tiền</th><th>Trạng thái</th><th /></tr></thead><tbody>{payments.map((payment) => <tr key={payment.id}><td>{payment.receipt_code}</td><td>{payment.paid_on}</td><td>{payment.method}</td><td>{money(payment.amount_vnd)}</td><td>{payment.reversed ? 'Đã hoàn tác' : 'Đã ghi nhận'}</td><td><div className="button-row"><button className="button button-quiet" onClick={() => downloadReceipt(payment.id)} type="button">Tải biên lai</button>{!payment.reversed && user.roles.some((role) => ['admin', 'accountant'].includes(role)) ? <button className="button button-quiet" onClick={() => reversePayment(payment)} type="button">Hoàn tác</button> : null}</div></td></tr>)}</tbody></table></div></section> : <div className="panel empty-state">Chưa có giao dịch trong phạm vi truy cập.</div>}
    {!loading && data ? <ListPagination page={page} pageSize={data.page_size} total={data.total} onPageChange={setPage} /> : null}
    {!studentView ? <><TuitionOperations notify={notify} user={user} /><FinanceReports notify={notify} /></> : null}
  </PageFrame>
}

type DebtRow = { installment_id: number; student_name: string; student_code: string | null; class_code: string; program_name: string | null; installment_number: number; due_date: string; remaining_vnd: string; status: string; overdue_days: number }
type DebtReport = { items: DebtRow[]; total: number; page: number; page_size: number; total_remaining_vnd: string; total_overdue_vnd: string }
type RevenueReport = { from_date: string | null; to_date: string | null; net_revenue_vnd: string; payment_count: number; reversal_count: number; monthly: { month: string; net_revenue_vnd: string }[]; by_class: { class_id: number; class_code: string | null; class_name: string | null; program_name: string | null; net_revenue_vnd: string; total_due_vnd: string; paid_vnd: string; remaining_vnd: string }[]; by_program: { program_name: string; net_revenue_vnd: string; total_due_vnd: string; paid_vnd: string; remaining_vnd: string }[] }

function FinanceReports({ notify }: { notify: (message: string) => void }) {
  const [page, setPage] = useState(1); const [status, setStatus] = useState(''); const [debts, setDebts] = useState<DebtReport | null>(null); const [revenue, setRevenue] = useState<RevenueReport | null>(null); const [from, setFrom] = useState(''); const [to, setTo] = useState('')
  const loadDebts = useCallback(() => { const query = new URLSearchParams({ page: String(page), page_size: '20', sort: 'due_date' }); if (status) query.set('status', status); apiRequest<DebtReport>(`/tuition-debts?${query}`).then(setDebts).catch((error: unknown) => notify(showError(error))) }, [notify, page, status])
  const loadRevenue = useCallback(() => { const query = new URLSearchParams(); if (from) query.set('from_date', from); if (to) query.set('to_date', to); apiRequest<RevenueReport>(`/tuition-revenue${query.size ? `?${query}` : ''}`).then(setRevenue).catch((error: unknown) => notify(showError(error))) }, [from, notify, to])
  useEffect(loadDebts, [loadDebts]); useEffect(loadRevenue, [loadRevenue])
  const exportData = async () => { try { const query = new URLSearchParams(); if (from) query.set('from_date', from); if (to) query.set('to_date', to); const blob = await apiBlobRequest(`/tuition-revenue/export.xlsx${query.toString() ? `?${query}` : ''}`); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'tuition-revenue.xlsx'; a.click(); URL.revokeObjectURL(url) } catch (error) { notify(showError(error)) } }
  const exportDebts = async () => { try { const query = new URLSearchParams(); if (status) query.set('status', status); const blob = await apiBlobRequest(`/tuition-debts/export.xlsx${query.toString() ? `?${query}` : ''}`); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'tuition-debts.xlsx'; a.click(); URL.revokeObjectURL(url) } catch (error) { notify(showError(error)) } }
  return <div className="finance-reports"><section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">CÔNG NỢ</span><h2>Khoản phải thu</h2></div><label className="form-field compact-field"><span>Lọc trạng thái</span><select value={status} onChange={(event) => { setPage(1); setStatus(event.target.value) }}><option value="">Tất cả</option><option value="overdue">Quá hạn</option><option value="partial">Đóng một phần</option><option value="unpaid">Chưa đóng</option><option value="paid">Đã đóng</option></select></label><button className="button button-quiet" onClick={exportDebts} type="button">Xuất công nợ Excel</button></div>{debts ? <><p className="finance-totals">Còn phải thu: <strong>{money(debts.total_remaining_vnd)}</strong> · Quá hạn: <strong>{money(debts.total_overdue_vnd)}</strong></p><div className="table-scroll"><table className="data-table"><thead><tr><th>Học viên</th><th>Lớp / chương trình</th><th>Đợt · hạn</th><th>Còn nợ</th><th>Trạng thái</th></tr></thead><tbody>{debts.items.map((row) => <tr key={row.installment_id}><td>{row.student_name} · {row.student_code ?? '—'}</td><td>{row.class_code} · {row.program_name ?? '—'}</td><td>{row.installment_number} · {row.due_date}</td><td>{money(row.remaining_vnd)}</td><td>{row.status}{row.overdue_days ? ` · trễ ${row.overdue_days} ngày` : ''}</td></tr>)}</tbody></table></div><ListPagination page={debts.page} pageSize={debts.page_size} total={debts.total} onPageChange={setPage} /></> : <div className="loading-panel">Đang tải công nợ…</div>}</section><section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">BÁO CÁO THU</span><h2>Doanh thu theo chương trình và lớp</h2></div><button className="button button-secondary" onClick={exportData} type="button">Xuất Excel</button></div><div className="filter-panel-fields"><label className="form-field"><span>Từ ngày</span><input type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></label><label className="form-field"><span>Đến ngày</span><input type="date" value={to} onChange={(event) => setTo(event.target.value)} /></label></div>{revenue ? <><div className="finance-totals">Doanh thu ròng: <strong>{money(revenue.net_revenue_vnd)}</strong> · Thu {revenue.payment_count} lần · Hoàn tác {revenue.reversal_count} lần</div><section className="revenue-monthly"><h3>Doanh thu ròng theo tháng</h3>{revenue.monthly.map((row) => <div className="revenue-month-row" key={row.month}><span>{row.month}</span><strong>{money(row.net_revenue_vnd)}</strong></div>)}</section><h3>Chi tiết theo lớp</h3><div className="table-scroll"><table className="data-table"><thead><tr><th>Lớp</th><th>Chương trình</th><th>Đã thu</th><th>Phải thu</th><th>Còn nợ</th></tr></thead><tbody>{revenue.by_class.map((row) => <tr key={row.class_id}><td>{row.class_code ?? '—'} · {row.class_name ?? ''}</td><td>{row.program_name ?? '—'}</td><td>{money(row.paid_vnd)}</td><td>{money(row.total_due_vnd)}</td><td>{money(row.remaining_vnd)}</td></tr>)}</tbody></table></div><h3>Chi tiết theo chương trình</h3><div className="table-scroll"><table className="data-table"><thead><tr><th>Chương trình</th><th>Đã thu</th><th>Phải thu</th><th>Còn nợ</th></tr></thead><tbody>{revenue.by_program.map((row, index) => <tr key={`${row.program_name}-${index}`}><td>{row.program_name}</td><td>{money(row.paid_vnd)}</td><td>{money(row.total_due_vnd)}</td><td>{money(row.remaining_vnd)}</td></tr>)}</tbody></table></div></> : <div className="loading-panel">Đang tải báo cáo doanh thu…</div>}</section></div>
}

type FeeSchedule = { id: number; program_id: number; version: number; amount_vnd: string; valid_from: string; valid_to: string | null }
type ClassChoice = { id: number; code: string; name: string; status: string; program_id: number | null }
type InstallmentDraft = { amount: string; due_date: string }

function TuitionOperations({ user, notify }: { user: User; notify: (message: string) => void }) {
  const [programs, setPrograms] = useState<Program[]>([]); const [classes, setClasses] = useState<ClassChoice[]>([]); const [programId, setProgramId] = useState(''); const [classId, setClassId] = useState(''); const [schedules, setSchedules] = useState<FeeSchedule[]>([]); const [scheduleId, setScheduleId] = useState(''); const [amount, setAmount] = useState(''); const [validFrom, setValidFrom] = useState(''); const [validTo, setValidTo] = useState(''); const [appliedOn, setAppliedOn] = useState(''); const [installments, setInstallments] = useState<InstallmentDraft[]>([{ amount: '', due_date: '' }]); const [planId, setPlanId] = useState(''); const [discountKind, setDiscountKind] = useState<'fixed' | 'percent'>('fixed'); const [discountValue, setDiscountValue] = useState(''); const [discountReason, setDiscountReason] = useState('')
  const canManageFeeSchedule = user.roles.some((role) => ['admin', 'accountant'].includes(role))
  useEffect(() => { apiRequest<Program[]>('/study-programs?page=1&page_size=100').then(setPrograms).catch((error: unknown) => notify(showError(error))) }, [notify])
  useEffect(() => { if (!programId) return; apiRequest<ClassChoice[]>(`/classes?page=1&page_size=100&program_id=${programId}`).then(setClasses).catch((error: unknown) => notify(showError(error))) }, [notify, programId])
  useEffect(() => { if (!programId) return; apiRequest<FeeSchedule[]>(`/study-programs/${programId}/fee-schedules?page=1&page_size=100`).then(setSchedules).catch((error: unknown) => notify(showError(error))) }, [notify, programId])
  const createSchedule = async (event: FormEvent) => { event.preventDefault(); try { const saved = await apiRequest<FeeSchedule>(`/study-programs/${programId}/fee-schedules`, { method: 'POST', body: JSON.stringify({ amount_vnd: Number(amount), valid_from: validFrom, valid_to: validTo || null }) }); setSchedules((rows) => [...rows, saved]); setScheduleId(String(saved.id)); notify(`Đã tạo biểu phí phiên bản ${saved.version}.`) } catch (error) { notify(showError(error)) } }
  const createPlans = async (event: FormEvent) => { event.preventDefault(); try { const result = await apiRequest<{ created_count: number; skipped_count: number }>('/tuition-plans/batch', { method: 'POST', body: JSON.stringify({ class_id: Number(classId), fee_schedule_id: Number(scheduleId), applied_on: appliedOn, installments: installments.map((item) => ({ amount_vnd: Number(item.amount), due_date: item.due_date })) }) }); notify(`Đã tạo ${result.created_count} kế hoạch; bỏ qua ${result.skipped_count} kế hoạch đã có.`) } catch (error) { notify(showError(error)) } }
  const requestDiscount = async (event: FormEvent) => { event.preventDefault(); try { const result = await apiRequest<{ id: number; amount_vnd: string; status: string }>(`/tuition-plans/${Number(planId)}/discounts`, { method: 'POST', body: JSON.stringify({ kind: discountKind, value: Number(discountValue), reason: discountReason }) }); notify(`Yêu cầu giảm #${result.id}: ${money(result.amount_vnd)} · ${result.status}.`); setDiscountReason('') } catch (error) { notify(showError(error)) } }
  return <section className="panel tuition-operations"><div className="panel-heading"><div><span className="eyebrow">KẾ HOẠCH VÀ GIẢM HỌC PHÍ</span><h2>Thiết lập nghĩa vụ học phí</h2></div></div><div className="finance-operations-grid">{canManageFeeSchedule ? <form className="finance-operation-card" onSubmit={createSchedule}><h3>Biểu phí chương trình</h3><label className="form-field"><span>Chương trình</span><select required value={programId} onChange={(event) => { setProgramId(event.target.value); setClasses([]); setSchedules([]); setScheduleId(''); setClassId('') }}><option value="">Chọn chương trình</option>{programs.map((program) => <option key={program.id} value={program.id}>{program.code} · {program.name}</option>)}</select></label><label className="form-field"><span>Tổng học phí (VND)</span><input min="1" required type="number" value={amount} onChange={(event) => setAmount(event.target.value)} /></label><label className="form-field"><span>Bắt đầu hiệu lực</span><input required type="date" value={validFrom} onChange={(event) => setValidFrom(event.target.value)} /></label><label className="form-field"><span>Kết thúc hiệu lực (tùy chọn)</span><input type="date" value={validTo} onChange={(event) => setValidTo(event.target.value)} /></label><button className="button button-primary" disabled={!programId} type="submit">Tạo biểu phí</button>{schedules.length ? <label className="form-field"><span>Biểu phí hiện có</span><select value={scheduleId} onChange={(event) => setScheduleId(event.target.value)}><option value="">Chọn biểu phí</option>{schedules.map((schedule) => <option key={schedule.id} value={schedule.id}>v{schedule.version} · {money(schedule.amount_vnd)} · {schedule.valid_from}</option>)}</select></label> : null}</form> : null}<form className="finance-operation-card" onSubmit={createPlans}><h3>Tạo kế hoạch hàng loạt cho lớp</h3><label className="form-field"><span>Lớp</span><select required value={classId} onChange={(event) => setClassId(event.target.value)}><option value="">Chọn lớp</option>{classes.filter((item) => item.status !== 'cancelled').map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><label className="form-field"><span>Biểu phí ID</span><select required value={scheduleId} onChange={(event) => setScheduleId(event.target.value)}><option value="">Chọn biểu phí đã nạp ở cột bên</option>{schedules.map((schedule) => <option key={schedule.id} value={schedule.id}>#{schedule.id} · {money(schedule.amount_vnd)}</option>)}</select></label><label className="form-field"><span>Ngày áp dụng</span><input required type="date" value={appliedOn} onChange={(event) => setAppliedOn(event.target.value)} /></label>{installments.map((item, index) => <div className="installment-editor" key={index}><label className="form-field"><span>Đợt {index + 1} · VND</span><input min="1" required type="number" value={item.amount} onChange={(event) => setInstallments((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, amount: event.target.value } : row))} /></label><label className="form-field"><span>Hạn đóng</span><input required type="date" value={item.due_date} onChange={(event) => setInstallments((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, due_date: event.target.value } : row))} /></label>{installments.length > 1 ? <button aria-label={`Xóa đợt ${index + 1}`} className="button button-quiet" onClick={() => setInstallments((current) => current.filter((_, rowIndex) => rowIndex !== index))} type="button">Xóa</button> : null}</div>)}<button className="button button-quiet" disabled={installments.length >= 24} onClick={() => setInstallments((current) => [...current, { amount: '', due_date: '' }])} type="button">Thêm đợt</button><button className="button button-primary" disabled={!classId || !scheduleId} type="submit">Tạo kế hoạch cho lớp</button></form><form className="finance-operation-card" onSubmit={requestDiscount}><h3>Yêu cầu giảm học phí</h3><label className="form-field"><span>Mã kế hoạch học phí</span><input min="1" required type="number" value={planId} onChange={(event) => setPlanId(event.target.value)} /></label><label className="form-field"><span>Hình thức</span><select value={discountKind} onChange={(event) => setDiscountKind(event.target.value as 'fixed' | 'percent')}><option value="fixed">Số tiền cố định (VND)</option><option value="percent">Phần trăm</option></select></label><label className="form-field"><span>Giá trị giảm</span><input min="0.01" required step="0.01" type="number" value={discountValue} onChange={(event) => setDiscountValue(event.target.value)} /></label><label className="form-field"><span>Lý do</span><textarea maxLength={1000} required value={discountReason} onChange={(event) => setDiscountReason(event.target.value)} /></label><button className="button button-primary" type="submit">Gửi yêu cầu giảm</button></form></div></section>
}

export function DiscountReviewPage({ notify }: { user: User; notify: (message: string) => void }) {
  const [planId, setPlanId] = useState(''); const [rows, setRows] = useState<{ id: number; kind: string; value: string; amount_vnd: string; reason: string; status: string }[]>([]); const [busy, setBusy] = useState(false)
  const load = async () => { if (!planId) return; setBusy(true); try { setRows(await apiRequest<{ id: number; kind: string; value: string; amount_vnd: string; reason: string; status: string }[]>(`/tuition-plans/${planId}/discounts?page=1&page_size=100`)) } catch (error) { notify(showError(error)) } finally { setBusy(false) } }
  const decide = async (id: number, action: 'approve' | 'reject') => { try { await apiRequest(`/tuition-discounts/${id}/${action}`, { method: 'POST' }); notify(`Đã ${action === 'approve' ? 'duyệt' : 'từ chối'} yêu cầu giảm.`); await load() } catch (error) { notify(showError(error)) } }
  return <PageFrame eyebrow="TÀI CHÍNH · DUYỆT GIẢM" title="Duyệt yêu cầu giảm học phí"><section className="panel form-panel"><div className="button-row"><label className="form-field"><span>Mã kế hoạch</span><input inputMode="numeric" value={planId} onChange={(event) => setPlanId(event.target.value)} /></label><button className="button button-primary" disabled={!planId || busy} onClick={load} type="button">Tải yêu cầu</button></div>{rows.map((row) => <article className="discount-review-row" key={row.id}><div><strong>{money(row.amount_vnd)} · {row.value}{row.kind === 'percent' ? '%' : ' VND'}</strong><p>{row.reason}</p><span className={`status-badge status-${row.status}`}>{row.status}</span></div>{row.status === 'pending' ? <div className="button-row"><button className="button button-primary" onClick={() => decide(row.id, 'approve')} type="button">Duyệt</button><button className="button button-quiet" onClick={() => decide(row.id, 'reject')} type="button">Từ chối</button></div> : null}</article>)}{!rows.length && !busy ? <div className="empty-state">Nhập mã kế hoạch để xem các yêu cầu đã gửi.</div> : null}</section></PageFrame>
}

export function TranscriptPage({ notify }: { user: User; notify: (message: string) => void }) {
  const [data, setData] = useState<Transcript | null>(null); const [page, setPage] = useState(1); const [loading, setLoading] = useState(true)
  useEffect(() => { apiRequest<Transcript>(`/students/me/transcript?page=${page}&page_size=20`).then(setData).catch((error: unknown) => notify(showError(error))).finally(() => setLoading(false)) }, [notify, page])
  const exportPdf = async () => { try { const blob = await apiBlobRequest('/students/me/transcript.pdf'); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'transcript.pdf'; anchor.click(); URL.revokeObjectURL(url) } catch (error) { notify(showError(error)) } }
  return <PageFrame eyebrow="HỌC VỤ · SPRINT 8" title="Bảng điểm cá nhân" description="Kết quả học tập của tài khoản hiện tại; điểm tổng kết chỉ hiển thị sau khi được chốt.">
    <section className="metric-grid metric-grid-compact"><article className="metric-card"><span className="metric-label">Điểm trung bình khóa học</span><strong className="metric-value">{loading ? '…' : data?.course_average ?? '—'}</strong></article><article className="metric-card"><span className="metric-label">Môn học</span><strong className="metric-value">{loading ? '…' : data?.total ?? 0}</strong></article><article className="metric-card"><span className="metric-label">Ngày cấp</span><strong className="metric-value metric-value-date">{data?.issued_on ?? '—'}</strong></article></section>
    <section className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">TRANSCRIPT</span><h2>Kết quả theo môn</h2></div><button className="button button-secondary" onClick={exportPdf} type="button">Tải bảng điểm PDF</button></div>{loading ? <div className="loading-panel">Đang tải bảng điểm…</div> : data?.courses.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Môn học</th><th>Lớp</th><th>Điểm</th><th>Kết quả</th><th>Chốt lúc</th></tr></thead><tbody>{data.courses.map((course) => <tr key={course.course_id}><td>{course.course_name}</td><td>{course.classes.map((item) => item.class_code).join(', ')}</td><td>{course.final_score ?? 'Chưa chốt'}</td><td><span className={`status-badge status-${course.result}`}>{course.result}</span></td><td>{course.finalized_at ? dateTime(course.finalized_at) : '—'}</td></tr>)}</tbody></table></div> : <div className="empty-state">Chưa có kết quả học tập.</div>}</section>
    {data ? <ListPagination page={page} pageSize={data.page_size} total={data.total} onPageChange={setPage} /> : null}
  </PageFrame>
}

export function SurveysPage({ user, notify }: { user: User; notify: (message: string) => void }) {
  const isStudent = user.roles.includes('student') && !user.roles.some((role) => ['admin', 'manager'].includes(role))
  const [surveys, setSurveys] = useState<StudentSurvey[]>([]); const [loading, setLoading] = useState(true); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [answers, setAnswers] = useState<Record<number, Record<string, string | number>>>({}); const [busy, setBusy] = useState<number | null>(null)
  const load = useCallback(() => { apiRequestWithHeaders<StudentSurvey[]>(`/students/me/surveys?page=${page}&page_size=20`).then(({ data, headers }) => { setSurveys(data); setTotal(paginationFromHeaders(headers, { page, pageSize: 20 }).total) }).catch((error: unknown) => notify(showError(error))).finally(() => setLoading(false)) }, [notify, page])
  useEffect(() => { if (isStudent) load() }, [isStudent, load])
  const submit = async (event: FormEvent<HTMLFormElement>, survey: StudentSurvey) => { event.preventDefault(); setBusy(survey.survey_id); try { await apiRequest(`/surveys/${survey.survey_id}/responses`, { method: 'POST', body: JSON.stringify({ answers: answers[survey.survey_id] ?? {} }) }); notify('Phản hồi khảo sát đã được ghi nhận ẩn danh.'); load() } catch (error) { notify(showError(error)) } finally { setBusy(null) } }
  return <PageFrame eyebrow="PHẢN HỒI · SPRINT 8" title={isStudent ? 'Khảo sát cuối khóa' : 'Khảo sát lớp học'} description={isStudent ? 'Mỗi khảo sát chỉ nhận một phản hồi. Nội dung phản hồi không gắn với danh tính của bạn.' : 'Tạo khảo sát và xem báo cáo tổng hợp ẩn danh theo lớp.'}>
    {isStudent ? loading ? <div className="panel loading-panel">Đang tải khảo sát…</div> : surveys.length ? <>{surveys.map((survey) => <form className="panel survey-card" key={survey.survey_id} onSubmit={(event) => submit(event, survey)}><div className="panel-heading"><div><span className="eyebrow">{survey.class_name} · Hạn {dateTime(survey.deadline)}</span><h2>{survey.title}</h2></div><span className={`status-badge ${survey.responded ? 'status-success' : 'status-open'}`}>{survey.responded ? 'Đã phản hồi' : 'Chưa phản hồi'}</span></div>{survey.questions.map((question) => <label className="survey-question" key={question.id}><span>{question.prompt}{question.is_required ? ' *' : ''}</span>{question.question_type === 'rating' ? <select required={question.is_required} disabled={survey.responded} value={answers[survey.survey_id]?.[String(question.id)] ?? ''} onChange={(event) => setAnswers((current) => ({ ...current, [survey.survey_id]: { ...current[survey.survey_id], [String(question.id)]: Number(event.target.value) } }))}><option value="">Chọn mức đánh giá</option>{Array.from({ length: (question.scale_max ?? 5) - (question.scale_min ?? 1) + 1 }, (_, index) => (question.scale_min ?? 1) + index).map((score) => <option key={score} value={score}>{score}</option>)}</select> : <textarea required={question.is_required} disabled={survey.responded} maxLength={4000} value={String(answers[survey.survey_id]?.[String(question.id)] ?? '')} onChange={(event) => setAnswers((current) => ({ ...current, [survey.survey_id]: { ...current[survey.survey_id], [String(question.id)]: event.target.value } }))} />}</label>)}{!survey.responded ? <button className="button button-primary" disabled={busy === survey.survey_id} type="submit">{busy === survey.survey_id ? 'Đang gửi…' : 'Gửi phản hồi'}</button> : null}</form>)}<ListPagination page={page} pageSize={20} total={total} onPageChange={setPage} /></> : <div className="panel empty-state">Hiện không có khảo sát đang mở.</div> : <ManagerSurveyWorkspace notify={notify} isManager={user.roles.includes('manager')} />}
  </PageFrame>
}

function ManagerSurveyWorkspace({ notify, isManager }: { notify: (message: string) => void; isManager: boolean }) {
  const [classes, setClasses] = useState<{ id: number; code: string; name: string }[]>([]); const [classId, setClassId] = useState(''); const [title, setTitle] = useState(''); const [deadline, setDeadline] = useState(''); const [questions, setQuestions] = useState<{ prompt: string; question_type: 'rating' | 'text'; is_required: boolean }[]>([{ prompt: '', question_type: 'text', is_required: true }]); const [surveyId, setSurveyId] = useState(''); const [report, setReport] = useState<SurveyReport | null>(null); const [teacherId, setTeacherId] = useState(''); const [teachers, setTeachers] = useState<{ id: number; full_name: string; username: string }[]>([]); const [comparison, setComparison] = useState<SurveyComparison | null>(null); const [respondentProgress, setRespondentProgress] = useState<{ responded_student_ids: number[]; pending_student_ids: number[]; total: number } | null>(null); const [comparisonPage, setComparisonPage] = useState(1)
  useEffect(() => { apiRequest<{ items?: { id: number; code: string; name: string }[] } | { id: number; code: string; name: string }[]>('/classes?page=1&page_size=100').then((rows) => setClasses(Array.isArray(rows) ? rows : rows.items ?? [])).catch((error: unknown) => notify(showError(error))); apiRequest<{ items: { id: number; full_name: string; username: string }[] }>('/accounts?role=teacher&page=1&page_size=100').then((rows) => setTeachers(rows.items)).catch(() => undefined) }, [notify])
  const create = async (event: FormEvent) => { event.preventDefault(); try { const payloadQuestions = questions.map((item) => ({ ...item, ...(item.question_type === 'rating' ? { scale_min: 1, scale_max: 5 } : {}) })); const created = await apiRequest<{ id: number }>('/surveys', { method: 'POST', body: JSON.stringify({ class_id: Number(classId), title, deadline: new Date(deadline).toISOString(), questions: payloadQuestions }) }); setSurveyId(String(created.id)); notify(`Đã tạo khảo sát #${created.id}.`); setTitle(''); setQuestions([{ prompt: '', question_type: 'text', is_required: true }]) } catch (error) { notify(showError(error)) } }
  const loadReport = async () => { try { setReport(await apiRequest<SurveyReport>(`/surveys/${surveyId}/results`)) } catch (error) { notify(showError(error)) } }
  const exportReport = async () => { try { const blob = await apiBlobRequest(`/surveys/${surveyId}/results.xlsx`); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `survey-${surveyId}.xlsx`; a.click(); URL.revokeObjectURL(url) } catch (error) { notify(showError(error)) } }
  const loadComparison = async (nextPage = comparisonPage) => { if (!teacherId) return; try { setComparison(await apiRequest<SurveyComparison>(`/survey-reports/teachers/${teacherId}?page=${nextPage}&page_size=20`)); setComparisonPage(nextPage) } catch (error) { notify(showError(error)) } }
  const exportComparison = async () => { if (!teacherId) return; try { const blob = await apiBlobRequest(`/survey-reports/teachers/${teacherId}/export.xlsx`); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `teacher-${teacherId}-survey-comparison.xlsx`; a.click(); URL.revokeObjectURL(url) } catch (error) { notify(showError(error)) } }
  const loadRespondents = async () => { if (!surveyId) return; try { setRespondentProgress(await apiRequest<{ responded_student_ids: number[]; pending_student_ids: number[]; total: number }>(`/surveys/${surveyId}/respondents?page=1&page_size=100`)) } catch (error) { notify(showError(error)) } }
  return <div className="academic-workspace"><form className="panel form-panel" onSubmit={create}><div className="panel-heading"><div><span className="eyebrow">TẠO BIỂU MẪU</span><h2>Khảo sát lớp</h2></div></div><label className="form-field"><span>Lớp</span><select required value={classId} onChange={(event) => setClassId(event.target.value)}><option value="">Chọn lớp</option>{classes.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><label className="form-field"><span>Tiêu đề</span><input required maxLength={200} value={title} onChange={(event) => setTitle(event.target.value)} /></label>{questions.map((item, index) => <fieldset className="survey-question-editor" key={index}><legend>Câu hỏi {index + 1}</legend><label className="form-field"><span>Loại câu hỏi</span><select value={item.question_type} onChange={(event) => setQuestions((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, question_type: event.target.value as 'rating' | 'text' } : row))}><option value="text">Tự luận</option><option value="rating">Thang điểm 1–5</option></select></label><label className="form-field"><span>Nội dung câu hỏi</span><textarea required={item.is_required} maxLength={1000} value={item.prompt} onChange={(event) => setQuestions((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, prompt: event.target.value } : row))} /></label><label className="checkbox-field"><input checked={item.is_required} type="checkbox" onChange={(event) => setQuestions((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, is_required: event.target.checked } : row))} /><span>Bắt buộc</span></label>{questions.length > 1 ? <button className="button button-quiet" onClick={() => setQuestions((current) => current.filter((_, rowIndex) => rowIndex !== index))} type="button">Xóa câu hỏi</button> : null}</fieldset>)}<button className="button button-quiet" disabled={questions.length >= 50} onClick={() => setQuestions((current) => [...current, { prompt: '', question_type: 'text', is_required: true }])} type="button">Thêm câu hỏi</button><label className="form-field"><span>Hạn phản hồi</span><input required type="datetime-local" value={deadline} onChange={(event) => setDeadline(event.target.value)} /></label><button className="button button-primary" type="submit">Tạo khảo sát</button></form><section className="panel form-panel"><div className="panel-heading"><div><span className="eyebrow">BÁO CÁO ẨN DANH</span><h2>Kết quả khảo sát</h2></div></div><label className="form-field"><span>Mã khảo sát</span><input inputMode="numeric" value={surveyId} onChange={(event) => setSurveyId(event.target.value)} /></label><div className="button-row"><button className="button button-secondary" disabled={!surveyId} onClick={loadReport} type="button">Xem kết quả</button><button className="button button-quiet" disabled={!surveyId} onClick={exportReport} type="button">Xuất Excel</button>{isManager ? <button className="button button-quiet" disabled={!surveyId} onClick={loadRespondents} type="button">Tiến độ phản hồi</button> : null}</div>{respondentProgress ? <p className="finance-totals">Đã phản hồi {respondentProgress.responded_student_ids.length} / {respondentProgress.total} học viên</p> : null}{report ? <><p className="finance-totals"><strong>{report.title}</strong> · {report.class_name ?? `Lớp ${report.class_id}`} · {report.response_count} phản hồi ẩn danh</p><div className="table-scroll"><table className="data-table"><thead><tr><th>Câu hỏi</th><th>Loại</th><th>Số phản hồi</th><th>Điểm trung bình</th></tr></thead><tbody>{report.questions.map((question) => <tr key={question.question_id}><td>{question.prompt}</td><td>{question.question_type === 'rating' ? 'Thang điểm' : 'Tự luận'}</td><td>{question.response_count}</td><td>{question.average ?? '—'}</td></tr>)}</tbody></table></div>{report.text_answers.length ? <section className="survey-anonymous-answers"><h3>Ý kiến tự luận ẩn danh</h3>{report.text_answers.map((answer, index) => <article className="survey-answer-card" key={`${answer.question_id}-${index}`}><strong>{answer.prompt}</strong><p>{answer.answer}</p></article>)}</section> : null}</> : null}<p className="form-help">Báo cáo chỉ hiển thị thống kê và nội dung phản hồi ẩn danh từ backend.</p></section><section className="panel form-panel survey-comparison"><div className="panel-heading"><div><span className="eyebrow">SO SÁNH GIẢNG VIÊN</span><h2>Kết quả khảo sát theo giảng viên</h2></div></div><label className="form-field"><span>Giảng viên</span><select value={teacherId} onChange={(event) => setTeacherId(event.target.value)}><option value="">Chọn giảng viên</option>{teachers.map((teacher) => <option key={teacher.id} value={teacher.id}>{teacher.full_name} · {teacher.username}</option>)}</select></label><div className="button-row"><button className="button button-secondary" disabled={!teacherId} onClick={() => void loadComparison(1)} type="button">Xem so sánh</button><button className="button button-quiet" disabled={!teacherId} onClick={exportComparison} type="button">Xuất báo cáo Excel</button></div>{comparison ? <><div className="table-scroll"><table className="data-table"><thead><tr><th>Lớp / khảo sát</th><th>Phản hồi</th><th>Câu hỏi và điểm trung bình</th></tr></thead><tbody>{comparison.classes.map((survey) => <tr key={survey.survey_id}><td>{survey.class_name} · {survey.title}</td><td>{survey.response_count}</td><td>{survey.questions.map((question) => `${question.prompt}: ${question.average ?? '—'} (${question.response_count})`).join(' · ')}</td></tr>)}</tbody></table></div><ListPagination page={comparison.page} pageSize={comparison.page_size} total={comparison.total} onPageChange={(next) => void loadComparison(next)} /></> : null}</section></div>
}

export function GraduationPage({ notify }: { user: User; notify: (message: string) => void }) {
  const [programs, setPrograms] = useState<Program[]>([]); const [programId, setProgramId] = useState(''); const [rows, setRows] = useState<GraduationStudent[]>([]); const [selected, setSelected] = useState<number[]>([]); const [loading, setLoading] = useState(false); const [threshold, setThreshold] = useState('20'); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [view, setView] = useState<'eligibility' | 'history'>('eligibility'); const [history, setHistory] = useState<{ id: number; student_id: number; confirmed_by: number; confirmed_at: string }[]>([])
  useEffect(() => { apiRequest<Program[] | { items?: Program[] }>('/study-programs?page=1&page_size=100').then((data) => setPrograms(Array.isArray(data) ? data : data.items ?? [])).catch((error: unknown) => notify(showError(error))) }, [notify])
  const loadEligibility = async (targetPage = page) => { if (!programId) return; setLoading(true); try { const response = await apiRequest<{ eligible: GraduationStudent[]; ineligible: GraduationStudent[]; total: number }>(`/study-programs/${programId}/graduation-eligibility?page=${targetPage}&page_size=20`); setRows([...response.eligible, ...response.ineligible]); setTotal(response.total); setPage(targetPage); setSelected([]) } catch (error) { notify(showError(error)) } finally { setLoading(false) } }
  const loadHistory = async (targetPage = page) => { if (!programId) return; setLoading(true); try { const result = await apiRequestWithHeaders<{ id: number; student_id: number; confirmed_by: number; confirmed_at: string }[]>(`/study-programs/${programId}/graduations/history?page=${targetPage}&page_size=20`); setHistory(result.data); setTotal(paginationFromHeaders(result.headers, { page: targetPage, pageSize: 20 }).total); setPage(targetPage) } catch (error) { notify(showError(error)) } finally { setLoading(false) } }
  const saveThreshold = async (event: FormEvent) => { event.preventDefault(); try { await apiRequest(`/study-programs/${programId}/graduation-policy`, { method: 'PUT', body: JSON.stringify({ attendance_threshold_percent: Number(threshold) }) }); notify('Đã lưu ngưỡng chuyên cần.'); await loadEligibility() } catch (error) { notify(showError(error)) } }
  const confirm = async () => { if (!programId || !selected.length || !window.confirm(`Xác nhận tốt nghiệp cho ${selected.length} học viên?`)) return; try { await apiRequest(`/study-programs/${programId}/graduations/confirm`, { method: 'POST', body: JSON.stringify({ student_ids: selected }) }); notify(`Đã xác nhận ${selected.length} học viên.`); await loadEligibility() } catch (error) { notify(showError(error)) } }
  return <PageFrame eyebrow="HỌC VỤ · SPRINT 8" title="Điều kiện tốt nghiệp" description="Kiểm tra điểm, chuyên cần và công nợ trước khi xác nhận tốt nghiệp."><section className="panel form-panel"><div className="graduation-controls"><label className="form-field"><span>Chương trình</span><select value={programId} onChange={(event) => { setProgramId(event.target.value); setPage(1); setRows([]); setHistory([]) }}><option value="">Chọn chương trình</option>{programs.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><form onSubmit={saveThreshold} className="form-inline"><label className="form-field"><span>Ngưỡng chuyên cần (%)</span><input type="number" min="0" max="100" step="0.01" value={threshold} onChange={(event) => setThreshold(event.target.value)} /></label><button className="button button-secondary" disabled={!programId} type="submit">Lưu ngưỡng</button></form><div className="button-row"><button className={`button ${view === 'eligibility' ? 'button-primary' : 'button-quiet'}`} disabled={!programId || loading} onClick={() => { setView('eligibility'); void loadEligibility(1) }} type="button">Điều kiện</button><button className={`button ${view === 'history' ? 'button-primary' : 'button-quiet'}`} disabled={!programId || loading} onClick={() => { setView('history'); void loadHistory(1) }} type="button">Lịch sử xác nhận</button></div></div>{view === 'eligibility' ? rows.length ? <><div className="table-scroll"><table className="data-table"><thead><tr><th><input aria-label="Chọn tất cả học viên đủ điều kiện" type="checkbox" onChange={(event) => setSelected(event.target.checked ? rows.filter((row) => row.eligible).map((row) => row.student_id) : [])} /></th><th>Học viên</th><th>Điều kiện</th><th>Chi tiết</th></tr></thead><tbody>{rows.map((row) => <tr key={row.student_id}><td><input aria-label={`Chọn ${row.student_name}`} checked={selected.includes(row.student_id)} disabled={!row.eligible} type="checkbox" onChange={(event) => setSelected((current) => event.target.checked ? [...current, row.student_id] : current.filter((id) => id !== row.student_id))} /></td><td>{row.student_name} · {row.student_code ?? row.student_id}</td><td>{row.eligible ? 'Đủ điều kiện' : 'Chưa đủ điều kiện'}</td><td>{row.reason_details?.join(' · ') || 'Đạt tiêu chí hiện hành'}</td></tr>)}</tbody></table></div><button className="button button-primary" disabled={!selected.length} onClick={confirm} type="button">Xác nhận tốt nghiệp ({selected.length})</button><ListPagination page={page} pageSize={20} total={total} onPageChange={(next) => void loadEligibility(next)} /></> : <div className="empty-state">{loading ? 'Đang tải danh sách…' : 'Chọn chương trình rồi tải điều kiện tốt nghiệp.'}</div> : history.length ? <><div className="table-scroll"><table className="data-table"><thead><tr><th>Học viên ID</th><th>Người xác nhận ID</th><th>Thời điểm</th></tr></thead><tbody>{history.map((event) => <tr key={event.id}><td>{event.student_id}</td><td>{event.confirmed_by}</td><td>{dateTime(event.confirmed_at)}</td></tr>)}</tbody></table></div><ListPagination page={page} pageSize={20} total={total} onPageChange={(next) => void loadHistory(next)} /></> : <div className="empty-state">{loading ? 'Đang tải lịch sử…' : 'Chọn chương trình để xem lịch sử xác nhận.'}</div>}</section></PageFrame>
}

export function DashboardApiPanel({ roles, notify }: { roles: Role[]; notify: (message: string) => void }) {
  const [data, setData] = useState<Record<string, unknown> | null>(null)
  const path = roles.some((role) => ['admin', 'manager'].includes(role)) ? '/dashboards/management' : roles.includes('teacher') ? '/dashboards/teacher' : ''
  useEffect(() => { if (path) apiRequest<Record<string, unknown>>(path).then(setData).catch((error: unknown) => notify(showError(error))) }, [notify, path])
  if (!path || !data) return null
  const cards = data.cards as Record<string, string | number | null> | undefined
  const nextClass = data.next_class as Record<string, string> | null | undefined
  const absenceRows = (data.high_absence_students ?? data.most_absent_students) as { student_id: number; student_name: string; class_id: number; class_code?: string; class_name?: string; absence_count: number; attendance_url?: string }[] | undefined
  const leadMonths = data.lead_intake_by_month as { year: number; month: number; intake: number }[] | undefined
  const leadFunnel = data.lead_funnel as { status: string; count: number }[] | undefined
  const maxLeadIntake = Math.max(1, ...(leadMonths ?? []).map((item) => item.intake))
  return <section className="panel dashboard-api-panel"><div className="panel-heading"><div><span className="eyebrow">DỮ LIỆU NGHIỆP VỤ</span><h2>{cards ? 'Tình hình đào tạo' : 'Việc cần ưu tiên'}</h2></div></div>{cards ? <div className="dashboard-api-metrics">{Object.entries(cards).map(([key, value]) => <article className="dashboard-api-metric" key={key}><span>{({ active_classes: 'Lớp đang hoạt động', active_students: 'Học viên đang học', attendance_average_percent: 'Chuyên cần trung bình', overdue_debt_vnd: 'Công nợ quá hạn' } as Record<string, string>)[key] ?? key}</span><strong>{key.endsWith('_vnd') ? money(String(value ?? 0)) : value == null ? '—' : key.endsWith('_percent') ? `${value}%` : Number(value).toLocaleString('vi-VN')}</strong></article>)}</div> : <div className="dashboard-api-metrics"><article className="dashboard-api-metric"><span>Lớp tiếp theo</span><strong>{nextClass ? `${nextClass.class_code} · ${nextClass.session_date} ${nextClass.start_time}` : 'Không có lớp sắp tới'}</strong>{nextClass ? <a href={`/classes/${nextClass.class_id}/attendance/matrix`}>Mở điểm danh</a> : null}</article><article className="dashboard-api-metric"><span>Bài chưa chấm</span><strong>{String(data.ungraded_submission_count ?? 0)}</strong><a href="/assignments">Mở hàng chờ chấm</a></article><article className="dashboard-api-metric"><span>Học viên vắng nhiều</span><strong>{absenceRows?.length ?? 0}</strong></article></div>}{leadMonths?.length ? <div className="dashboard-chart"><h3>Lead tiếp nhận theo tháng</h3><div className="monthly-bars" role="list">{leadMonths.map((item) => <div className="monthly-bar-item" key={`${item.year}-${item.month}`} role="listitem" title={`${item.month}/${item.year}: ${item.intake}`}><span>{item.intake}</span><i style={{ height: `${Math.max(6, item.intake * 100 / maxLeadIntake)}%` }} /><small>{String(item.month).padStart(2, '0')}</small></div>)}</div></div> : null}{leadFunnel?.length ? <div className="dashboard-funnel"><h3>Phễu tuyển sinh</h3>{leadFunnel.map((item) => <div className="funnel-row" key={item.status}><span>{item.status}</span><strong>{item.count.toLocaleString('vi-VN')}</strong></div>)}</div> : null}{absenceRows?.length ? <div className="dashboard-absence-list"><h3>Học viên cần theo dõi</h3>{absenceRows.map((row) => <a className="dashboard-absence-row" href={`/classes/${row.class_id}/attendance/matrix`} key={`${row.student_id}-${row.class_id}`}><span><strong>{row.student_name}</strong><small>{row.class_code ?? row.class_name ?? `Lớp ${row.class_id}`}</small></span><span className="status-badge status-tone-warning">Vắng {row.absence_count} buổi</span></a>)}</div> : null}</section>
}
